// 真实 NSWindow/ObjC 视图回调，焦点参数由夹具显式驱动，不验证系统前台激活。
pub(crate) fn native_bridge_probe() {
    use crate::{platform::{InputContext,ProtectedInput,protected_input::{InputCommand,InputKind}},resources::Budget,
        ssh::auth::{Backend,Kind,Owner,editor::{Editor,NativeAction}},tasks::Cancellation};
    use std::{sync::Arc,time::Instant};
    struct Host {source:Option<InputContext>,editor:Option<Editor>,front:crate::ssh::auth::Front,plain:usize,inputs:usize,commands:usize}
    impl App for Host {
        fn event(&mut self,event:Event)->bool{if let Event::Key{key:Key::F(1),..}=event {self.plain+=1;}else{panic!("ordinary input escaped")};true}
        fn protected_context(&self)->Option<InputContext>{self.source.clone()}
        fn protected_input(&mut self,input:ProtectedInput)->bool{
            let kind=input.kind();let editor=self.editor.as_mut().unwrap();
            let action=editor.native_input(editor.token(),&self.front,input).unwrap();self.inputs+=1;
            if kind==InputKind::Command{self.commands+=1;assert!(matches!(action,NativeAction::Edited|NativeAction::Cancel));}true
        }
        fn tick(&mut self)->bool{true}
        fn needs_redraw(&self)->bool{false}
        fn draw(&mut self)->Option<(&Framebuffer,crate::render::Damage)>{None}
        fn take_title(&mut self)->Option<String>{None}
        fn deadline(&self)->Option<Instant>{None}
        fn take_clipboard_request(&mut self)->Option<ClipboardRequest>{None}
        fn ime_cursor_area(&self)->(u32,u32,u32,u32){(12,12,8,16)}
    }
    unsafe fn key(view:Id,window:Id,code:u16,flags:usize,text:&str){unsafe{
        let number:isize=msg![window,"windowNumber";isize];let text=nsstring(text);
        let event:Id=msg![class(c"NSEvent"),"keyEventWithType:location:modifierFlags:timestamp:windowNumber:context:characters:charactersIgnoringModifiers:isARepeat:keyCode:",10usize=>usize,NSPoint{x:0.0,y:0.0}=>NSPoint,flags=>usize,0.0f64=>f64,number=>isize,NIL=>Id,text=>Id,text=>Id,0i8=>i8,code=>u16;Id];
        msg![view,"keyDown:",event=>Id;()];
    }}
    unsafe fn wakes(app:Id)->usize{unsafe{
        let past:Id=msg![class(c"NSDate"),"distantPast";Id];let mut count=0;
        loop{let event:Id=msg![app,"nextEventMatchingMask:untilDate:inMode:dequeue:",1u64<<NS_EVENT_TYPE_APPLICATION_DEFINED=>u64,past=>Id,NSDefaultRunLoopMode=>Id,1i8=>i8;Id];if event.is_null(){return count;}count+=1;assert!(count<32);}
    }}
    unsafe {
        let outer=objc_autoreleasePoolPush();let budget=Budget::new(128*1024,0);let cancel=Cancellation::default();
        let (mut back,front)=Backend::new(Owner{session:11,generation:2},&budget,Arc::new(||{})).unwrap();
        back.begin(Kind::Secret,b"complete public fixture identity",&cancel).unwrap();
        let mut editor=Editor::new(&front,front.snapshot().input.unwrap()).unwrap();editor.commit(editor.token(),"seed".into()).unwrap();
        let window=Window::new("Congminal input bridge validation",|_|(400,220)).unwrap();
        let mut host=Host{source:None,editor:Some(editor),front,plain:0,inputs:0,commands:0};
        let ordinary:Id=msg![window.view,"inputContext";Id];assert!(!ordinary.is_null());
        key(window.view,window.window,122,0,"");
        while let Some(event)=IME.with(|s|s.borrow_mut().events.pop_front()) {assert!(protected_window::plain_event(window.view,event,&mut host));}
        assert_eq!(host.plain,1);
        let editor=host.editor.as_mut().unwrap();host.source=Some(editor.input_context(editor.token(),&host.front).unwrap());
        assert!(protected_window::sync(window.view,true,&mut host));
        let protected_window::Lookup::Active(handle)=protected_window::lookup(window.view) else{panic!()};
        assert_eq!(msg![window.view,"inputContext";Id],handle.raw());
        let retained:Id=msg![handle.raw(),"retain";Id];let old_client:Id=msg![handle.raw(),"client";Id];drop(handle);
        key(window.view,window.window,0,NS_COMMAND,"a");
        assert!(protected_window::drain(window.view,true,&mut host));
        assert_eq!(host.editor.as_mut().unwrap().mask().selection,Some(0..4));
        let _=wakes(window.app);
        let protected_window::Lookup::Active(handle)=protected_window::lookup(window.view) else{panic!()};
        let client:Id=msg![handle.raw(),"client";Id];drop(handle);
        for text in ["组","组合"]{msg![client,"setMarkedText:selectedRange:replacementRange:",nsstring(text)=>Id,NSRange{location:0,length:0}=>NSRange,NSRange{location:0,length:0}=>NSRange;()];}
        let wake_count=wakes(window.app);assert_eq!(wake_count,1);
        assert!(protected_window::drain(window.view,true,&mut host));assert_eq!(host.editor.as_mut().unwrap().mask().preedit,2);
        msg![client,"insertText:replacementRange:",nsstring("typed")=>Id,NSRange{location:0,length:0}=>NSRange;()];
        assert!(protected_window::drain(window.view,true,&mut host));assert_eq!(host.editor.as_mut().unwrap().mask().characters,5);
        protected_window::blur(window.view);assert!(protected_window::sync(window.view,false,&mut host));
        assert!(msg![window.view,"inputContext";Id].is_null());
        let before=host.inputs;
        msg![old_client,"insertText:replacementRange:",nsstring("OLD_PUBLIC_FIXTURE")=>Id,NSRange{location:0,length:0}=>NSRange;()];
        assert!(protected_window::drain(window.view,false,&mut host));assert_eq!(host.inputs,before);
        host.editor.take();let mut editor=Editor::new(&host.front,host.front.snapshot().input.unwrap()).unwrap();
        host.source=Some(editor.input_context(editor.token(),&host.front).unwrap());host.editor=Some(editor);
        assert!(protected_window::sync(window.view,true,&mut host));
        msg![old_client,"insertText:replacementRange:",nsstring("OLD_PUBLIC_FIXTURE")=>Id,NSRange{location:0,length:0}=>NSRange;()];
        assert!(protected_window::drain(window.view,true,&mut host));assert_eq!(host.inputs,before);
        assert_eq!(host.editor.as_mut().unwrap().mask().characters,0);
        assert!(protected_window::plain_event(window.view,Event::Text("UNSCOPED_PUBLIC_FIXTURE".into()),&mut host));
        key(window.view,window.window,53,0,"");assert!(protected_window::drain(window.view,true,&mut host));
        assert_eq!(host.commands,2);
        // 菜单粘贴也携带原身份；先在客户端取出后切源，交接必须按旧身份拒绝。
        paste(window.view,std::ptr::null(),NIL);
        let protected_window::Lookup::Active(handle)=protected_window::lookup(window.view) else{panic!()};
        let stale=handle.pop().unwrap();assert_eq!(stale.command(),Some(InputCommand::Paste));drop(handle);
        host.editor.take();let mut editor=Editor::new(&host.front,host.front.snapshot().input.unwrap()).unwrap();let token=editor.token();
        host.source=Some(editor.input_context(token,&host.front).unwrap());
        assert!(editor.native_input(token,&host.front,stale).is_err());host.editor=Some(editor);
        assert!(protected_window::sync(window.view,true,&mut host));
        host.source=None;assert!(protected_window::sync(window.view,true,&mut host));
        assert_eq!(msg![window.view,"inputContext";Id],ordinary);
        msg![retained,"release";()];let inputs=host.inputs;drop((host,window,back));objc_autoreleasePoolPop(outer);
        assert_eq!(budget.snapshot().used,0);
        eprintln!("IME_BRIDGE plain_keys=1 commands=2 inputs={inputs} coalesced_wakes={wake_count} late_deliveries=0 final_used=0");
    }
}
